def parse_u64(value_str, flag_name):
    # Mimic Rust parse::<u64> errors
    # value_str is str
    if value_str == "":
        return None, "cannot parse integer from empty string"
    # Check for leading +? Rust allows single leading +?
    s = value_str
    if s[0] == '+':
        if len(s)==1:
            return None, "invalid digit found in string"
        s_body = s[1:]
        # s_body must be digits, no other +/-
        # Check overflow later
        # Validate digits
        for ch in s_body:
            if ch < '0' or ch > '9':
                return None, "invalid digit found in string"
        # Now parse
        try:
            v = int(value_str, 10)  # Python int handles +?
            # Check range 0..2**64-1
            if v < 0 or v >= 2**64:
                return None, "number too large to fit in target type"
            return v, None
        except ValueError:
            # Python int with base 10 for large? Actually int can handle big, but we already checked digits, so overflow is the only case?
            # For overflow, int will succeed but >2**64-1, handled above
            return None, "invalid digit found in string"
    elif s[0] == '-':
        return None, "invalid digit found in string"
    else:
        # Must be all digits
        for ch in s:
            if ch < '0' or ch > '9':
                return None, "invalid digit found in string"
        # Parse
        try:
            v = int(s, 10)
            if v >= 2**64:
                return None, "number too large to fit in target type"
            return v, None
        except:
            return None, "invalid digit found in string"

def eprint(s):
    sys.stderr.write(s)

def print_clap_error(prog, msg, usage=None, tip=None):
    # msg is like "unexpected argument '--unknown' found" etc.
    # usage is like "[OPTIONS] [FILE]..." or "--check <FILE>..." etc. Full "Usage: prog ..." line?
    # For generic errors, usage is "[OPTIONS] [FILE]..."
    # For conflicts, usage varies
    # tip is optional
    eprint(f"error: {msg}\n")
    if tip:
        eprint(f"\n  tip: {tip}\n")
    if usage:
        eprint(f"\nUsage: {prog} {usage}\n")
    eprint(f"\nFor more information, try '--help'.\n")

