def parse_u64(s, flag_disp):
    if s=="":
        return None, "cannot parse integer from empty string"
    if s[0]=='+':
        if len(s)==1:
            return None, "invalid digit found in string"
        body=s[1:]
        for ch in body:
            if ch<'0' or ch>'9':
                return None, "invalid digit found in string"
        try:
            v=int(s,10)
        except:
            return None, "invalid digit found in string"
        if v>=2**64:
            return None, "number too large to fit in target type"
        return v, None
    elif s[0]=='-':
        return None, "invalid digit found in string"
    else:
        for ch in s:
            if ch<'0' or ch>'9':
                return None, "invalid digit found in string"
        try:
            v=int(s,10)
        except:
            return None, "invalid digit found in string"
        if v>=2**64:
            return None, "number too large to fit in target type"
        return v, None

KNOWN_LONGS = {"--keyed","--derive-key","--length","--seek","--num-threads","--no-mmap","--no-names","--raw","--tag","--check","--quiet","--help","--version"}
def is_known_flag_like(a):
    if a=="-" or a=="--":
        return False
    if a.startswith("--"):
        if "=" in a:
            base=a.split("=",1)[0]
            return base in KNOWN_LONGS
        else:
            return a in KNOWN_LONGS
    elif a.startswith("-"):
        # short
        if a in ("-l","-c","-h","-V"):
            return True
        if len(a)>=2 and a[1]=='l':
            return True
        if len(a)>=2 and a[1] in ('c','h','V','l'):
            return True
        return False
    return False

def clap_unexpected(prog, arg_disp):
    sys.stderr.write(f"error: unexpected argument '{arg_disp}' found\n\n  tip: to pass '{arg_disp}' as a value, use '-- {arg_disp}'\n\nUsage: {prog} [OPTIONS] [FILE]...\n\nFor more information, try '--help'.\n")
    sys.exit(2)
def clap_missing(prog, flag_disp):
    sys.stderr.write(f"error: a value is required for '{flag_disp}' but none was supplied\n\nFor more information, try '--help'.\n")
    sys.exit(2)
def clap_invalid(prog, val, flag_disp, kind):
    sys.stderr.write(f"error: invalid value '{val}' for '{flag_disp}': {kind}\n\nFor more information, try '--help'.\n")
    sys.exit(2)
def clap_conflict(prog, first, second, usage):
    sys.stderr.write(f"error: the argument '{first}' cannot be used with '{second}'\n\nUsage: {prog} {usage}\n\nFor more information, try '--help'.\n")
    sys.exit(2)
def clap_required(prog, missing_list, usage):
    # missing_list like ["--check"] or ["--check", "<FILE>..."]
    sys.stderr.write(f"error: the following required arguments were not provided:\n")
    for m in missing_list:
        sys.stderr.write(f"  {m}\n")
    sys.stderr.write(f"\nUsage: {prog} {usage}\n\nFor more information, try '--help'.\n")
    sys.exit(2)
def clap_unexpected_value(prog, val, flag):
    sys.stderr.write(f"error: unexpected value '{val}' for '{flag}' found; no more were expected\n\nUsage: {prog} {flag} [FILE]...\n\nFor more information, try '--help'.\n")
    sys.exit(2)
