def needs_escape(s):
    return ('\\' in s) or ('\n' in s) or ('\r' in s)
def escape_name(s):
    return s.replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r")
def unescape_name(s):
    # s is raw filename string (after stripping leading \, before unescaping)
    # Returns (unescaped, error?) error is "Invalid backslash escape" if invalid
    res=[]
    i=0
    while i < len(s):
        if s[i]=='\\':
            if i+1>=len(s):
                return None, True
            nxt=s[i+1]
            if nxt=='\\':
                res.append('\\'); i+=2
            elif nxt=='n':
                res.append('\n'); i+=2
            elif nxt=='r':
                res.append('\r'); i+=2
            else:
                return None, True
        else:
            res.append(s[i]); i+=1
    return ''.join(res), False

def read_data_for_hash(path, is_check=False):
    # For hash mode (non-check) and check mode hashed files (not checkfiles)
    # path is str, "-" means stdin
    # Returns (data_bytes or None, error_str or None)
    # For hash mode, error_str is "No such file..." etc. for stderr with b3sum: prefix (handled by caller)
    # For check mode hashed files, error is for stdout FAILED (...) (handled by caller)
    # Here just read and return data or exception
    if path=="-":
        # stdin
        try:
            data=sys.stdin.buffer.read()
            return data, None
        except Exception as e:
            return None, str(e)
    else:
        try:
            # Check if directory? open will fail with IsADirectoryError
            # Use open in binary
            with open(path,'rb') as f:
                return f.read(), None
        except FileNotFoundError as e:
            return None, (e.strerror, e.errno)
        except IsADirectoryError as e:
            return None, (e.strerror, e.errno)
        except OSError as e:
            # Generic
            return None, (e.strerror if e.strerror else str(e), e.errno if e.errno is not None else 1)

